<div class="gsm-card order-table-card"><div class="table-tools"><div class="input-group"><span class="input-group-text"><i class="fas fa-search"></i></span><input id="orderSearch" class="form-control" placeholder="Search by ID, service or device"></div><select id="statusFilter" class="form-select"><option value="">All statuses</option><option>waiting</option><option>inprogress</option><option>success</option><option>rejected</option><option>cancelled</option></select></div><div class="table-responsive"><table class="table align-middle mb-0" id="ordersTable"><thead><tr><th>Order</th><th>Service</th><th>Device / target</th><th>Status</th><th>Amount</th><th>Date</th><th></th></tr></thead><tbody>@forelse($orders as $order)<tr data-status="{{ strtolower($order['status']) }}"><td><strong>#{{ $order['id'] }}</strong><div class="small text-muted">{{ strtoupper($order['type']) }}</div></td><td class="fw-semibold">{{ $order['service'] }}</td><td>{{ str($order['device'])->limit(34) }}</td><td><span class="status-action status-{{ str($order['status'])->lower()->replace(' ','-') }}">{{ ucfirst($order['status']) }}</span></td><td>${{ number_format((float)$order['amount'],2) }}</td><td>{{ $order['created_at']?->format('Y-m-d H:i') }}</td><td><button type="button" class="btn btn-sm btn-view-order" data-url="{{ route('customer.orders.show',[$order['type'],$order['id']]) }}"><i class="fas fa-eye"></i> View</button></td></tr>@empty<tr><td colspan="7" class="empty-state"><i class="fas fa-box-open"></i><h4>No orders yet</h4><p>Choose a service and your first order will appear here.</p></td></tr>@endforelse</tbody></table></div></div>
