@push('scripts')<script>const q=document.getElementById('orderSearch'),s=document.getElementById('statusFilter');function filterOrders(){document.querySelectorAll('#ordersTable tbody tr[data-status]').forEach(r=>r.hidden=!(r.innerText.toLowerCase().includes(q.value.toLowerCase())&&(!s.value||r.dataset.status===s.value)))}q?.addEventListener('input',filterOrders);s?.addEventListener('change',filterOrders);document.querySelectorAll('.btn-view-order').forEach(b=>b.addEventListener('click',async()=>{const body=document.getElementById('orderModalBody'),modal=window.bootstrap.Modal.getOrCreateInstance(document.getElementById('orderDetailsModal'));body.innerHTML='<div class="modal-loading"><i class="fas fa-spinner fa-spin"></i> Loading order…</div>';modal.show();try{const r=await fetch(b.dataset.url,{headers:{Accept:'application/json'}}),j=await r.json();body.innerHTML=r.ok?j.html:'<div class="alert alert-danger">Unable to load this order.</div>'}catch(e){body.innerHTML='<div class="alert alert-danger">Unable to load this order.</div>'}}))</script>@endpush
